});

import * as assert from 'node:assert/strict';
import * as test from 'node:test';

import { throttle } from './throttle.ts';

test.test('throttle', async (t) => {
  const threshold = 50;

  await t.test('should call functions as usual if they exceed threshold interval', (t) => {
    const fn = t.mock.fn();
    t.mock.timers.enable({ apis: ['setTimeout', 'Date'] });
    const fnThrottled = throttle(fn, threshold);

    fnThrottled(1);
    assert.deepEqual(fn.mock.calls[0].arguments, [1]);

    t.mock.timers.tick(threshold);
    fnThrottled(2);
    assert.deepEqual(fn.mock.calls[1].arguments, [2]);
  });

  await t.test('should trigger last call at the end of threshold', (t) => {
    const fn = t.mock.fn();
    t.mock.timers.enable({ apis: ['setTimeout', 'Date'] });
    const fnThrottled = throttle(fn, threshold);

    fnThrottled(1);
    assert.deepEqual(fn.mock.calls[0].arguments, [1]);
    t.mock.timers.tick(10);

    fnThrottled(2);
    t.mock.timers.tick(threshold - 10);
    assert.deepEqual(fn.mock.calls[1].arguments, [2]);
  });

  await t.test(
    'should call not more than once per threshold and preserve correct call order',
    (t) => {
      const fn = t.mock.fn();
      t.mock.timers.enable({ apis: ['setTimeout', 'Date'] });
      const fnThrottled = throttle(fn, threshold);

      fnThrottled(1);
      // call function immediately after the first call
      assert.deepEqual(fn.mock.calls[0].arguments, [1]);

      fnThrottled(2);
      fnThrottled(3);
      t.mock.timers.tick(threshold - 10); // 40ms
      // throttle following calls until the threshold is reached
      assert.deepEqual(fn.mock.calls[0].arguments, [1]);

      fnThrottled(4);
      t.mock.timers.tick(10); // 50ms
      // call function with last arguments after the threshold is reached
      assert.deepEqual(fn.mock.calls[1].arguments, [4]);

      t.mock.timers.tick(10); // 60ms
      fnThrottled(5);
      // don't call function immediately and wait until threshold reached
      assert.deepEqual(fn.mock.callCount(), 2);

      t.mock.timers.tick(threshold - 10); // 100ms
      assert.deepEqual(fn.mock.calls[2].arguments, [5]);
    },
  );

  await t.test('should cancel throttled call', (t) => {
    const fn = t.mock.fn();
    t.mock.timers.enable({ apis: ['setTimeout', 'Date'] });
    const fnThrottled = throttle(fn, threshold);

    fnThrottled(1);
    fnThrottled(2);
    fnThrottled(3);
    fnThrottled.cancel();
    t.mock.timers.tick(threshold);

    assert.equal(fn.mock.callCount(), 1);
    assert.deepEqual(fn.mock.calls[0].arguments, [1]);
  });
});

import * as assert from 'node:assert/strict';
import * as test from 'node:test';
import { createElement } from 'react';
import { hasReactNode, isPrimitiveReactNode } from './react_utils.ts';

test.test('hasReactNode', async (t) => {
  await t.test('return false cases', async (t) => {
    await t.test('should be false for value is undefined', () => {
      assert.equal(hasReactNode(undefined), false);
    });

    await t.test('should be false for value is null', () => {
      assert.equal(hasReactNode(null), false);
    });

    await t.test('should be false for value is false', () => {
      assert.equal(hasReactNode(false), false);
    });

    await t.test('should be false for value is empty string', () => {
      assert.equal(hasReactNode(''), false);
    });
  });

  await t.test('return true cases', async (t) => {
    await t.test('should be true for value is zero', () => {
      assert.equal(hasReactNode(0), true);
    });

    await t.test('should be true for value is not empty string', () => {
      assert.equal(hasReactNode(' '), true);
    });

    await t.test('should be true for value is react element', () => {
      assert.equal(hasReactNode(createElement('div')), true);
    });
  });
});

test.test('isPrimitiveReactNode', async (t) => {
  await t.test('return false cases', async (t) => {
    await t.test('should be false for value is boolean', () => {
      assert.equal(isPrimitiveReactNode(false), false);
    });

    await t.test('should be false for value is react element', () => {
      assert.equal(isPrimitiveReactNode(createElement('div')), false);
    });
  });

  await t.test('return true cases', async (t) => {
    await t.test('should be false for value is undefined', () => {
      assert.equal(isPrimitiveReactNode(''), true);
    });

    await t.test('should be false for value is null', () => {
      assert.equal(isPrimitiveReactNode(0), true);
    });
  });
});

import * as assert from 'node:assert/strict';
import * as test from 'node:test';
import {
  transliteratorGostLetterCombinationsRu,
  transliteratorVKEngToRus,
  transliteratorVKRusToEng,
} from './transliteration.ts';

test.test('transliteration', async (t) => {
  await Promise.all(
    [
      ['Славься, Отечество наше свободное,', 'Slavsya, Otechestvo nashe svobodnoe,'],
      ['Братских народов союз вековой,', 'Bratskikh narodov soyuz vekovoy,'],
      ['Предками данная мудрость народная!', 'Predkami dannaya mudrost narodnaya!'],
      ['Славься, страна! Мы гордимся тобой!', 'Slavsya, strana! My gordimsya toboy!'],
    ].map(
      async ([input, expected]) =>
        await t.test(
          `transliteratorVKRusToEng.transliteration(${JSON.stringify(input)}) should equal ${JSON.stringify(expected)}`,
          () => {
            assert.equal(transliteratorVKRusToEng.transliteration(input), expected);
          },
        ),
    ),
  );

  await Promise.all(
    [['VKontakte', 'ВКонтакте']].map(
      async ([input, expected]) =>
        await t.test(
          `transliteratorVKEngToRus.transliteration(${JSON.stringify(input)}) should equal ${JSON.stringify(expected)}`,
          () => {
            assert.equal(transliteratorVKEngToRus.transliteration(input), expected);
          },
        ),
    ),
  );

  await Promise.all(
    [
      ['Славься, Отечество наше свободное,', 'Slav`sya, Otechestvo nashe svobodnoe,'],
      ['Братских народов союз вековой,', 'Bratskix narodov soyuz vekovoj,'],
      ['Предками данная мудрость народная!', 'Predkami dannaya mudrost` narodnaya!'],
      ['Славься, страна! Мы гордимся тобой!', 'Slav`sya, strana! My` gordimsya toboj!'],
    ].map(
      async ([input, expected]) =>
        await t.test(
          `transliteratorGostLetterCombinationsRu.transliteration(${JSON.stringify(input)}) should equal ${JSON.stringify(expected)}`,
          () => {
            assert.equal(transliteratorGostLetterCombinationsRu.transliteration(input), expected);
          },
        ),
    ),
  );
});

import * as assert from 'node:assert/strict';
import * as test from 'node:test';
import { uniqueArrayFallback } from '../internal/uniqueArray.ts';
import { chunkArray, createArray, uniqueArray } from './arrays.ts';

test.it('createArray', () => {
  assert.deepEqual(createArray(0), []);
  assert.deepEqual(createArray(2), [0, 1]);
  assert.deepEqual(createArray(4, 2), [2, 3, 4, 5]);
});

test.it('chunkArray', () => {
  assert.deepEqual(chunkArray(null as unknown as readonly unknown[], 1), []);
  assert.deepEqual(chunkArray(undefined as unknown as readonly unknown[], 1), []);
  assert.deepEqual(chunkArray(0 as unknown as readonly unknown[], 1), []);

  assert.deepEqual(chunkArray([], 0), []);
  assert.deepEqual(chunkArray([1, 2], 0), [[1, 2]]);

  assert.deepEqual(chunkArray([], 1), []);

  const array3 = [1, 1, 1];

  assert.deepEqual(chunkArray(array3, 1), [[1], [1], [1]]);
  assert.deepEqual(chunkArray(array3, 2), [[1, 1], [1]]);
  assert.deepEqual(chunkArray(array3, 3), [[1, 1, 1]]);
  assert.deepEqual(chunkArray(array3, 4), [[1, 1, 1]]);

  const array4 = [1, 2, 3, 4];

  assert.deepEqual(chunkArray(array4, 1), [[1], [2], [3], [4]]);
  assert.deepEqual(chunkArray(array4, 2), [
    [1, 2],
    [3, 4],
  ]);
  assert.deepEqual(chunkArray(array4, 3), [[1, 2, 3], [4]]);
  assert.deepEqual(chunkArray(array4, 4), [array4]);
  assert.deepEqual(chunkArray(array4, 5), [array4]);
});

test.it('uniqueArray', async (t) => {
  const entries = [
    [null as unknown, []],
    [undefined as unknown, []],
    [0 as unknown, []],

    [
      [1, 1, 1, 2, 2, 2],
      [1, 2],
    ],

    [
      [1, 2, 2, 1, 1, 3],
      [1, 2, 3],
    ],

    [
      [1, 1, 2, 3, 5, 5, 7],
      [1, 2, 3, 5, 7],
    ],

    [
      ['a', 'a', 'b', 'a', 'c', 'a', 'd'],
      ['a', 'b', 'c', 'd'],
    ],

    [
      [0, '0', 0, 'false', false, false],
      [0, '0', 'false', false],
    ],
  ];

  await Promise.all(
    entries.map(
      async ([input, expected]) =>
        await t.test(
          `uniqueArray(${JSON.stringify(input)}) should equal ${JSON.stringify(expected)}`,
          () => {
            assert.deepEqual(uniqueArray(input as readonly unknown[]), expected);
          },
        ),
    ),
  );

  await Promise.all(
    entries.map(
      async ([input, expected]) =>
        await t.test(
          `uniqueArray(${JSON.stringify(input)}) should equal ${JSON.stringify(expected)} with no Set available`,
          () => {
            assert.deepEqual(uniqueArrayFallback(input as readonly unknown[]), expected);
          },
        ),
    ),
  );
});

