test.test('isPromiseLike', async (t) => {
  // biome-ignore lint/suspicious/noThenProperty: Testing isPromiseLike function
  const promise = { then: () => {} };

  const fn = () => {};
  // biome-ignore lint/suspicious/noThenProperty: Testing isPromiseLike function
  fn.then = () => {};

  await Promise.all(
    [promise, fn].map(
      async (input) =>
        await t.test(`isPromiseLike(${String(input)}) is true`, () => {
          assert.equal(isPromiseLike(input), true);
        }),
    ),
  );

  await Promise.all(
    // biome-ignore lint/suspicious/noThenProperty: Testing isPromiseLike function
    [{}, () => {}, { then: true }, [], [true]].map(
      async (input) =>
        await t.test(`isPromiseLike(${String(input)}) is false`, () => {
          assert.equal(isPromiseLike(input), false);
        }),
    ),
  );
});

import type { Dictionary } from './types.ts';

class CustomStorage {
  private data: Dictionary<string> = {};

  public setItem(key: string, val: string) {
    this.data[key] = String(val);
  }

  // biome-ignore lint/suspicious/noPrototypeBuiltins: hasOwn требует es2022
  public getItem = (key: string) => (this.data.hasOwnProperty(key) ? this.data[key] : null);

  public removeItem(id: string) {
    delete this.data[id];
  }

  public clear() {
    this.data = {};
  }

  public get length() {
    return Object.keys(this.data).length;
  }

  public key(index: number): string | null {
    return Object.keys(this.data)[index];
  }

  public keys = (): string[] => Object.keys(this.data);
}

const dummyKey = 'vk-ls-dummy';
const dummyContent = 'test';

let ls: CustomStorage | Storage;

function getLocalStorage() {
  if (ls) {
    return ls;
  }
  try {
    // Проверяем, нет ли в FF или Safari cross domain security restrictions
    window.localStorage.setItem(dummyKey, dummyContent);
    if (dummyContent !== window.localStorage.getItem(dummyKey)) {
      throw new Error('localStorage is broken');
    }
    window.localStorage.removeItem(dummyKey);
    ls = window.localStorage;
  } catch (_e) {
    ls = new CustomStorage();
  }
  return ls;
}

/**
 * Обертка над localStorage для кода, который может использоваться на других сайтах
 * Firefox блокирует доступ к localStorage для скриптов с других доменов
 */
export const localStorage = {
  setItem: (key: string, val: string): void => getLocalStorage().setItem(key, val),
  getItem: (key: string): string | null => getLocalStorage().getItem(key),
  removeItem: (key: string): void => getLocalStorage().removeItem(key),
  clear: (): void => getLocalStorage().clear(),
  length: (): number => getLocalStorage().length,
  key: (index: number): string | null => getLocalStorage().key(index),
  keys(): string[] {
    const storage = getLocalStorage();
    if (storage instanceof CustomStorage) {
      return storage.keys();
    } else {
      return Object.keys(storage);
    }
  },
  getPrefixedKeys: (prefix: string): string[] => {
    return localStorage.keys().filter((key) => key.startsWith(prefix));
  },
};

let sessionStorageCache: CustomStorage | Storage;

function getSessionStorage() {
  if (sessionStorageCache) {
    return sessionStorageCache;
  }
  try {
    // Проверяем, нет ли в FF или Safari cross domain security restrictions
    window.sessionStorage.setItem(dummyKey, dummyContent);
    if (dummyContent !== window.sessionStorage.getItem(dummyKey)) {
      throw new Error('sessionStorage is broken');
    }
    window.sessionStorage.removeItem(dummyKey);
    sessionStorageCache = window.sessionStorage;
  } catch (_e) {
    sessionStorageCache = new CustomStorage();
  }
  return sessionStorageCache;
}

export const sessionStorage = {
  setItem: (key: string, val: string): void => getSessionStorage().setItem(key, val),
  getItem: (key: string): string | null => getSessionStorage().getItem(key),
  removeItem: (key: string): void => getSessionStorage().removeItem(key),
  clear: (): void => getSessionStorage().clear(),
  length: (): number => getSessionStorage().length,
  key: (index: number): string | null => getSessionStorage().key(index),
  keys(): string[] {
    const storage = getSessionStorage();
    if (storage instanceof CustomStorage) {
      return storage.keys();
    } else {
      return Object.keys(storage);
    }
  },
  getPrefixedKeys: (prefix: string): string[] => {
    return sessionStorage.keys().filter((key) => key.startsWith(prefix));
  },
};

import * as assert from 'node:assert/strict';
import * as test from 'node:test';
import { querystring } from './querystring.ts';

test.test('querystring parse', async (t) => {
  await t.test('string starting with a `?`, `#` or `&`', () => {
    assert.deepEqual(querystring.parse('?foo=bar&xyz=baz'), { foo: 'bar', xyz: 'baz' });
    assert.deepEqual(querystring.parse('#foo=bar&xyz=baz'), { foo: 'bar', xyz: 'baz' });
    assert.deepEqual(querystring.parse('&foo=bar&xyz=baz'), { foo: 'bar', xyz: 'baz' });
  });

  await Promise.all(
    [0, false, null, {}, '?', 'https://vk.com'].map(
      async (query) =>
        await t.test(`querystring.parse(${String(query)}) is {}`, () => {
          assert.deepEqual(querystring.parse(query), {});
        }),
    ),
  );

  await Promise.all(
    [
      { query: 'http://www.google.com/?foo=bar?', expected: { foo: 'bar?' } },
      {
        query: 'ascii=%3Ckey%3A+0x90%3E',
        expected: { ascii: '<key: 0x90>' },
      },
      {
        query: 'a=%3B',
        expected: { a: ';' },
      },
      {
        query: 'a%3Bb=1',
        expected: { 'a;b': '1' },
      },
    ].map(
      async ({ query, expected }) =>
        await t.test(`querystring.parse(${String(query)}) is ${String(expected)}`, () => {
          assert.deepEqual(querystring.parse(query), expected);
        }),
    ),
  );

  // TODO: Написать больше тестов
});

test.test('querystring stringify', async (t) => {
  await t.test('empty string for null, undefined or empty data', () => {
    // @ts-expect-error TS2345: JS type check
    assert.deepEqual(querystring.stringify(null), '');
    // @ts-expect-error TS2345: JS type check
    assert.deepEqual(querystring.stringify(undefined), '');
    assert.deepEqual(querystring.stringify({}), '');
  });

  await t.test('base', () => {
    assert.deepEqual(querystring.stringify({ foo: 'bar' }), 'foo=bar');
    assert.deepEqual(querystring.stringify({ foo: 'bar', baz: 2 }), 'foo=bar&baz=2');
  });

  await t.test('encoding', () => {
    assert.deepEqual(
      querystring.stringify({ foo: 'bar', baz: 'foo & bar' }),
      'foo=bar&baz=foo%20%26%20bar',
    );
    assert.deepEqual(
      querystring.stringify({ foo: 'bar', baz: 'foo & bar' }, { encode: true }),
      'foo=bar&baz=foo%20%26%20bar',
    );
    assert.deepEqual(
      querystring.stringify({ foo: 'bar', baz: 'foo & bar' }, { encode: false }),
      'foo=bar&baz=foo & bar',
    );
  });

  await t.test('arrays', () => {
    assert.deepEqual(querystring.stringify({ foo: [1, 2, 3] }), 'foo[]=1&foo[]=2&foo[]=3');
    assert.deepEqual(
      querystring.stringify({ foo: ['a', 'foo & bar'] }),
      'foo[]=a&foo[]=foo%20%26%20bar',
    );
  });

  await t.test('null and undefined', () => {
    assert.deepEqual(querystring.stringify({ a: 'foo', b: undefined, c: null }), 'a=foo&c=');
    assert.deepEqual(
      querystring.stringify({ a: 'foo', b: undefined, c: null }, { skipNull: true }),
      'a=foo',
    );
  });
});
